// Endpoint contains information of an endpoint.
// TODO(i/8757) : Replace Endpoint with resolver.Endpoint struct.
type Endpoint struct {
	ResolverEndpoint resolver.Endpoint
	HealthStatus     EndpointHealthStatus
	Weight           uint32
	HashKey          string
	Metadata         map[string]any
}

// hostnameKeyType is the key to store the hostname attribute in
// a resolver.Endpoint.
type hostnameKeyType struct{}

// hashKey extracts and returns the hash key from the given endpoint metadata.
// If no hash key is found, it returns an empty string.
func hashKeyFromMetadata(metadata map[string]any) string {
	envoyLB, ok := metadata["envoy.lb"].(StructMetadataValue)
	if ok {
		if h, ok := envoyLB.Data["hash_key"].(string); ok {
			return h
		}
	}
	return ""
}

// EndpointConfig contains configuration corresponding to the endpoints in a
// cluster. Only one of EDSUpdate or DNSEndpoints will be populated based on the
// cluster type.
type EndpointConfig struct {
	// Endpoint configurartion for the EDS clusters.
	EDSUpdate *EndpointsUpdate
	// Endpoint configuration for the LOGICAL_DNS clusters.
	DNSEndpoints *DNSUpdate
	// ResolutionNote stores error encountered while obtaining endpoints data
	// for the cluster. It will contain a nil value when a valid endpoint data is
	// received. It contains an error when:
	//   - an invalid resource is received from the management server or
	//   - the endpoint resource does not exist on the management server
	ResolutionNote error
}

// EndpointsUpdate contains an EDS update.
type EndpointsUpdate struct {
	Drops []OverloadDropConfig
	// Localities in the EDS response with `load_balancing_weight` field not set
	// or explicitly set to 0 are ignored while parsing the resource, and
	// therefore do not show up here.
	Localities []Locality

	// Raw is the resource from the xds response.
	Raw *anypb.Any
}

